import{_ as t,o as l,c as e,a6 as r}from"./chunks/framework.BrkgobfX.js";const d=JSON.parse('{"title":"第十二章：未来（AGI）","description":"从 Chatbot 到 Agent、具身智能与世界模型——通向 AGI 的技术拼图与能力边界。","frontmatter":{"title":"第十二章：未来（AGI）","description":"从 Chatbot 到 Agent、具身智能与世界模型——通向 AGI 的技术拼图与能力边界。","source":"https://daiw.org/manual/bit-to-agi/12-future"},"headers":[],"relativePath":"manual/llm/bit-to-agi/12-future.md","filePath":"manual/llm/bit-to-agi/12-future.md"}'),o={name:"manual/llm/bit-to-agi/12-future.md"};function i(u,a,n,m,s,g){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="第十二章-未来-agi" tabindex="-1">第十二章：未来（AGI） <a class="header-anchor" href="#第十二章-未来-agi" aria-label="Permalink to &quot;第十二章：未来（AGI）&quot;">​</a></h1><blockquote><p>从 Chatbot 到 Agent、具身智能与世界模型——通向 AGI 的技术拼图与能力边界。</p></blockquote><p>前面十一章把 LLM 从比特讲到训练、推理与工程部署。本章转向<strong>应用形态与未来方向</strong>：模型不再只「说话」，而是调用工具、操作电脑、驱动机器人、在内部维护世界模型（若想从零手写生产级 Coding Agent 并精读工业界源码，推荐配合阅读<a href="https://daiw.org/manual/llm-to-agent" target="_blank" rel="noreferrer">《从 LLM 到 Agent》</a>、<a href="https://daiw.org/manual/claude-code" target="_blank" rel="noreferrer">《Claude Code 实战手册》</a>、<a href="https://daiw.org/manual/codex" target="_blank" rel="noreferrer">《Codex CLI 实战手册》</a>与<a href="https://daiw.org/manual/codex-source" target="_blank" rel="noreferrer">《Codex CLI 源码精读》</a>）。这些能力叠加起来，常被称作通向 AGI 的路径——但每块拼图都有<strong>可量化的上限</strong>，本章会反复强调。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>AGI（通用人工智能）至今<strong>没有公认定义，也没有系统通过严格验收</strong>。下文讨论的是 2024–2026 年可见的工程进展与瓶颈，不是科幻预测。</p></div><h2 id="本章目录" tabindex="-1">本章目录 <a class="header-anchor" href="#本章目录" aria-label="Permalink to &quot;本章目录&quot;">​</a></h2><ul><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/what-is-agent">Agent 是什么</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/memory">Memory</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/tool-use">Tool</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/mcp-future">MCP</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/computer-use">Computer Use</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/robotics">Robotics</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/world-model">World Model</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/agi-roadmap">AGI 路线图</a></li><li><a href="/Front2Full/manual/llm/bit-to-agi/12-future/safety-and-alignment">安全与对齐</a></li></ul><p>建议按顺序阅读。全部读完后请参阅<a href="/Front2Full/manual/llm/bit-to-agi/12-future/chapter-summary">本章总结</a>。查全书术语见专栏底部的 <a href="/Front2Full/manual/llm/bit-to-agi/ai-glossary">AI术语大全</a>。</p>',7)])])}const c=t(o,[["render",i]]);export{d as __pageData,c as default};
